parameters.jsCode:
const req = $("Prepare notification cursor").first().json,
  pages = $input.all().map((x) => x.json),
  tables = $("Get Table Schema")
    .all()
    .map((x) => x.json),
  events = [];
let cursor = req.cursor;
for (const page of pages) {
  if (!Array.isArray(page.payloads) || !Number.isSafeInteger(page.cursor) || page.cursor < cursor)
    throw Error("Invalid payload page");
  cursor = page.cursor;
  for (const p of page.payloads) {
    if (!Number.isSafeInteger(p.baseTransactionNumber) || !p.changedTablesById)
      throw Error("Invalid payload transaction");
    for (const [tableId, changes] of Object.entries(p.changedTablesById)) {
      const table = tables.find((t) => t.id === tableId);
      if (!table || !Array.isArray(table.fields)) throw Error("No matching table schema");
      const fields = table.fields
        .filter((f) => f.description)
        .map((f) => ({ id: f.id, name: f.name, type: f.type, description: f.description }));
      for (const [key, type] of [
        ["createdFieldsById", "field.created"],
        ["changedFieldsById", "field.updated"],
      ])
        for (const fieldId of Object.keys(changes[key] || {})) {
          const field = fields.find((f) => f.id === fieldId);
          if (field)
            events.push({
              baseId: req.baseId,
              tableId,
              event_type: type,
              field,
              fields,
              eventId:
                req.webhookId +
                ":" +
                p.baseTransactionNumber +
                ":" +
                tableId +
                ":" +
                type +
                ":" +
                fieldId,
            });
        }
      for (const rowId of Object.keys(changes.changedRecordsById || {}))
        events.push({
          baseId: req.baseId,
          tableId,
          event_type: "row.updated",
          rowId,
          fields,
          eventId: req.webhookId + ":" + p.baseTransactionNumber + ":" + tableId + ":row:" + rowId,
        });
    }
  }
}
return (events.length ? events : [{ event_type: "none" }]).map((json) => ({
  json: { ...json, cursor },
}));

