const x = $("Airtable Webhook").first().json.body,
  baseId = x?.base?.id,
  webhookId = x?.webhook?.id;
if (!/^app[A-Za-z0-9]+$/.test(baseId || "") || !/^ach[A-Za-z0-9]+$/.test(webhookId || ""))
  throw Error("Invalid notification");
const state = $getWorkflowStaticData("global"),
  key = baseId + ":" + webhookId;
return [{ json: { baseId, webhookId, key, cursor: state[key] || 1 } }];

const p = $("Prepare notification cursor").first().json,
  pages = $("Get Webhook Payload")
    .all()
    .map((i) => i.json),
  last = pages[pages.length - 1];
if (!last || last.mightHaveMore || !Number.isSafeInteger(last.cursor))
  throw Error("Incomplete payload pages");
const state = $getWorkflowStaticData("global");
state[p.key] = last.cursor;
return [{ json: { cursor: last.cursor } }];

const items = $input.all();
if (items.length === 1 && !items[0].json.id) return [{ json: { empty: true } }];
if (items.some((i) => !i.json.File?.[0]?.url)) throw Error("Invalid File in fetched record");
return items;

const mode = "direct";
if (!["direct", "relay"].includes(mode)) throw Error("Choose direct or relay");
return { json: { ...$json, relay: mode === "relay" } };

const event = $("Event Ref").item.json,
  row = $("Row Reference").item.json;
return {
  json: {
    baseId: event.baseId,
    tableId: event.tableId,
    recordId: row.id,
    eventId: event.eventId,
    text: $json.text,
    fields: [event.field],
  },
};

const event = $("Event Ref").item.json,
  row = $("Row Reference").item.json,
  fields = Object.fromEntries(Object.entries($json).filter(([k]) => k !== "id"));
return {
  json: {
    key: "airtable-pdf:" + event.eventId + ":" + event.tableId + ":" + row.id,
    baseId: event.baseId,
    tableId: event.tableId,
    recordId: row.id,
    payload: JSON.stringify(fields),
  },
};

if ($json.id !== $("Reserve record update").item.json.record_id)
  throw Error("Wrong record receipt");
return { json: $json };

const mode = "direct";
if (!["direct", "relay"].includes(mode)) throw Error("Choose direct or relay");
return { json: { ...$json, relay: mode === "relay" } };

const row = $("Row Ref").item.json,
  event = $("Event Ref1").item.json,
  fields = event.fields.filter((f) => f.description && !row[f.name]);
return {
  json: {
    baseId: event.baseId,
    tableId: event.tableId,
    recordId: row.id,
    eventId: event.eventId,
    text: $json.text,
    fields,
  },
};

const row = $("Row Ref").item.json,
  fields = $("Event Ref1").item.json.fields;
return { json: { ...$json, hasFields: fields.some((f) => f.description && !row[f.name]) } };

const event = $("Event Ref1").item.json,
  row = $("Row Ref").item.json,
  fields = Object.fromEntries(Object.entries($json).filter(([k]) => k !== "id"));
return {
  json: {
    key: "airtable-pdf:" + event.eventId + ":" + event.tableId + ":" + row.id,
    baseId: event.baseId,
    tableId: event.tableId,
    recordId: row.id,
    payload: JSON.stringify(fields),
  },
};

if ($json.id !== $("Reserve record update1").item.json.record_id)
  throw Error("Wrong record receipt");
return { json: $json };
